/// The faces of the composer's primary action (`ComposerPrimaryFace` in
/// composer-shell.tsx), in the web's order.
enum JunoShellPrimaryFace: String, CaseIterable, Sendable {
    case send
    case stop
    case voice
    case busy

    /// The accent disc, or the quiet secondary one. The accent means one verb.
    var isAccented: Bool {
        switch self {
        case .send: true
        case .stop: true
        case .voice: false
        case .busy: true
        }
    }

    /// The glyph, or nil where the system draws the face (a spinner).
    var icon: JunoIcon? {
        switch self {
        case .send: .send
        case .stop: .stop
        case .voice: .audioLines
        case .busy: nil
        }
    }

    /// The face the web's composer shows for one of its states (`PRIMARY_FACES`).
    init?(composerState: String) {
        switch composerState {
        case "checking": self = .busy
        case "stop": self = .stop
        case "send": self = .send
        case "voice": self = .voice
        default: return nil
        }
    }
}

/// The Settings rail (`SETTINGS_SECTIONS` in settings-sections.ts), in order.
enum JunoShellSettingsSection: String, CaseIterable, Sendable {
    case general
    case personalization
    case memory
    case models
    case connectors
    case devices
    case voice
    case data
    case account
    case billing

    /// What an unknown or missing section opens.
    static let defaultSection: Self = .general

    /// The web's words.
    var label: String {
        switch self {
        case .general: "General"
        case .personalization: "Personalization"
        case .memory: "Memory"
        case .models: "Models"
        case .connectors: "Apps"
        case .devices: "Devices"
        case .voice: "Voice"
        case .data: "Data & privacy"
        case .account: "Account"
        case .billing: "Plan & usage"
        }
    }

    var icon: JunoIcon {
        switch self {
        case .general: .general
        case .personalization: .personalization
        case .memory: .memory
        case .models: .models
        case .connectors: .connectors
        case .devices: .device
        case .voice: .voice
        case .data: .data
        case .account: .account
        case .billing: .billing
        }
    }

    /// The `/settings` URL for the section: the default is the bare page.
    var href: String {
        self == Self.defaultSection ? "/settings" : "/settings?section=\(rawValue)"
    }

    /// The other names the web routes to a section (`ALIASES`).
    static let aliases: [String: Self] = [
        "profile": .account,
        "security": .account,
        "permissions": .devices,
        "macs": .devices,
        "hosts": .devices,
        "connected-apps": .connectors,
        "connector-permissions": .connectors,
        "usage": .billing,
        "plan": .billing,
        "plan-usage": .billing,
        "appearance": .general,
        "theme": .general,
        "language": .general,
        "chat": .personalization,
        "style": .personalization,
        "instructions": .personalization,
        "danger": .account,
        "privacy": .data,
    ]

    /// The web's rule: a section id, else an alias, else the default.
    static func resolve(_ value: String?) -> Self {
        guard let value else { return defaultSection }
        return Self(rawValue: value) ?? aliases[value] ?? defaultSection
    }
}

/// The languages the shared string table carries (`strings.locales`).
enum JunoShellLanguage: String, CaseIterable, Sendable {
    case en
    case fr

    /// The app's language: the first localization the bundle resolves to.
    static var current: Self {
        let preferred = Bundle.main.preferredLocalizations.first ?? "en"
        return Self(rawValue: String(preferred.prefix(2)).lowercased()) ?? .en
    }

    enum PluralCategory: Sendable { case one, other }

    /// CLDR integer plural rules: English `one` is 1; French `one` is 0 and 1.
    func plural(_ count: Int) -> PluralCategory {
        switch self {
        case .en: count == 1 ? .one : .other
        case .fr: count == 0 || count == 1 ? .one : .other
        }
    }
}

